**Student Performance Evaluation Program**
=====================================

### Overview

This program evaluates student performance based on their scores in different subjects.

### Code
```python
class Student:
    def __init__(self, name, subjects):
        self.name = name
        self.subjects = subjects
        self.grades = {}

    def add_grade(self, subject, score):
        self.grades[subject] = score

    def calculate_average(self):
        total = sum(self.grades.values())
        return total / len(self.grades)

    def evaluate_performance(self):
        average = self.calculate_average()
        if average >= 80:
            return "Excellent"
        elif average >= 60:
            return "Good"
        else:
            return "Needs Improvement"


class School:
    def __init__(self):
        self.students = {}

    def add_student(self, student):
        self.students[student.name] = student

    def evaluate_all_students(self):
        for student in self.students.values():
            print(f"{student.name}: {student.evaluate_performance()}")


